1422: Check("an off-contact pressed mouse does not freeze the oil's own movement or keep deforming it",()=>
1423: {
1424:     var sim=Fresh();var c=sim.Selected!;sim.State.Creatures.RemoveAll(o=>o.Id!=c.Id);sim.State.RoomObjects.Clear();c.X=c.Z=0;c.Fullness=90;
1425:     sim.SetInteractionHand(3,0,true);c.Interaction.FollowPlayer=true;c.Interaction.Hydration=90;
1426:     var input=new InteractionInput(InteractionAction.Press,BodyPart.Side,Force:.3,Duration:.1);
1427:     sim.BeginInteractionGesture(c.Id,input);sim.ContinueInteractionGesture(input,true);double health=c.Health;
1428:     sim.ContinueInteractionGesture(input,false);
1429:     for(int frame=0;frame<15;frame++){sim.SetInteractionHand(3,0,true);Tick(sim,1);}
1430:     Require(c.X>.1&&c.Health>=health&&InteractionPresentation.Pose(c)!="pressure",$"empty mouse hold froze movement or continued pressure: X={c.X}, health={c.Health}/{health}, pose={InteractionPresentation.Pose(c)}");
1431:     sim.EndInteractionGesture();
1432: });

88: Check("保护者远离时不消除危险，实际走近后才能保护",()=>
89: {
90:     foreach(bool maternal in new[]{false,true})
91:     {
92:         var sim=Fixture(maternal);var protector=sim.State.Creatures[1];
93:         protector.X=protector.TargetX=-5;protector.Z=protector.TargetZ=-5;Tick(sim,.25);
94:         Require(HasThreat(sim.State.Creatures[0],maternal),"远处亲友自动保护");
95:         protector.X=protector.TargetX=maternal?.75:.825;protector.Z=protector.TargetZ=maternal?1.4:1.43;
96:         Tick(sim,.25);Require(!HasThreat(sim.State.Creatures[0],maternal),"实际在近处仍不保护");
97:     }
98: });
